import{_ as a,o as r,c as t,a2 as n}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"Procurement: orders, contracts and shared goals","description":"","frontmatter":{"pageId":"players/procurement","contentRevision":1},"headers":[],"relativePath":"en/players/procurement.md","filePath":"en/players/procurement.md"}'),o={name:"en/players/procurement.md"};function s(i,e,l,d,c,p){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="procurement-orders-contracts-and-shared-goals" tabindex="-1">Procurement: orders, contracts and shared goals <a class="header-anchor" href="#procurement-orders-contracts-and-shared-goals" aria-label="Permalink to &quot;Procurement: orders, contracts and shared goals&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p><strong>Buy order:</strong> specify a defName, quantity and unit price. The server reserves price × quantity; suppliers fulfill portions and are paid immediately.</p><p><strong>Directed contract:</strong> only the selected supplier sees the offer and must deliver the entire requested quantity at once.</p><p><strong>Shared goal:</strong> contributors&#39; resources remain in escrow until the goal is complete. The reward is then distributed proportionally; integer remainders go in ascending supplierId order, followed by the market fee. Cancellation returns resources to contributors and funds to the organizer.</p><p>Check the remaining quantity and deadline before confirming: an oversized delivery is not automatically split.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Only defName and quantity are matched: no quality, material, condition or pawn filters. Limits are 1,000,000 units, 720 hours, 1,000,000,000 silver and 100 deliveries; open orders are capped at min(20, MaxLotsPerPlayer). A previous supplier&#39;s freeze may prevent final goal settlement.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./economy">Wallet, mail and market</a></li><li><a href="./../admins/administration">Panel and moderation</a></li></ul>',11)])])}const h=a(o,[["render",s]]);export{m as __pageData,h as default};
